import fs from "node:fs";
import path from "node:path";
import { runEvaluationSet, summarizeEvaluation } from "../src/domain/evaluation";

const results = runEvaluationSet();
const summary = summarizeEvaluation(results);
const output = [
  "# Evaluation Results",
  "",
  "This report is generated by `npm run evaluate` from a hand-labeled, synthetic regression set. It evaluates deterministic safety boundaries; it is not a claim about live-search accuracy.",
  "",
  "## Summary",
  "",
  `- Cases passed: ${summary.passed}/${summary.cases}`,
  `- False dependency merges: ${summary.falseDependencyMerges}`,
  `- Missed explicit dependencies: ${summary.missedExplicitDependencies}`,
  `- Conclusions with inspectable evidence: ${summary.inspectableEvidencePercent}%`,
  "- API credits used: 0 (offline evaluation)",
  "",
  "## Cases",
  "",
  "| Case | Expected | Observed | Result |",
  "|---|---|---|---|",
  ...results.map((result) => `| ${escapeCell(result.caseName)} | ${escapeCell(result.expected)} | ${escapeCell(result.observed)} | ${result.passed ? "Pass" : "Fail"} |`),
  "",
  "## Interpretation",
  "",
  "The set emphasizes precision over recall. Exact identity and explicit republication wording can create deterministic grouping; similar wording alone cannot. Qualifier and denominator differences block equivalence. Inaccessible evidence remains unresolved rather than becoming negative evidence.",
  "",
  "Claim extraction, citation-support quality, live latency, provider failures, and actual credit use require labeled live investigations. Record those separately because fixture output cannot validate provider behavior.",
  "",
].join("\n");

fs.writeFileSync(path.join(process.cwd(), "docs", "evaluation.md"), output, "utf8");
console.log(JSON.stringify(summary, null, 2));
if (summary.passed !== summary.cases || summary.falseDependencyMerges > 0 || summary.missedExplicitDependencies > 0) process.exitCode = 1;

function escapeCell(value: string) {
  return value.replaceAll("|", "\\|").replaceAll("\n", " ");
}
